import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface AnimatedTextProps {
  text: string;
  element?: 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div' | 'li' | 'a';
  className?: string;
  preserveWhitespace?: boolean;
  onComplete?: () => void;
  delay?: number; // Add delay before starting animation
}

/**
 * AnimatedText component that renders text character by character
 * Uses a simpler sequential approach for better reliability
 */
const AnimatedText: React.FC<AnimatedTextProps> = ({
  text,
  element = 'span',
  className = '',
  preserveWhitespace = false,
  onComplete,
  delay = 0 // Default no delay
}) => {
  const [visibleChars, setVisibleChars] = useState(0);
  const [isComplete, setIsComplete] = useState(false);
  const [isStarted, setIsStarted] = useState(delay === 0);

  // Handle initial delay before starting animation
  useEffect(() => {
    if (delay > 0 && !isStarted) {
      const startTimer = setTimeout(() => {
        setIsStarted(true);
      }, delay);
      return () => clearTimeout(startTimer);
    }
  }, [delay, isStarted]);

  // Reset and start animation when text changes or when ready to start
  useEffect(() => {
    if (!isStarted) return;

    setVisibleChars(0);
    setIsComplete(false);

    let timeout: NodeJS.Timeout;
    let charIndex = 0;

    const animateNextChar = () => {
      if (charIndex < text.length) {
        charIndex++;
        setVisibleChars(charIndex);

        // Calculate next delay - longer for punctuation
        let delay = 30; // Base delay in ms

        // Slow down for punctuation
        const currentChar = text[charIndex - 1];
        if (['.', '!', '?', ',', ';', ':'].includes(currentChar)) {
          delay = 150; // Longer pause after punctuation
        }

        // Small random variation
        delay += Math.random() * 20 - 10;

        timeout = setTimeout(animateNextChar, delay);
      } else {
        setIsComplete(true);
        if (onComplete) {
          onComplete();
        }
      }
    };

    // Small initial delay before starting
    timeout = setTimeout(animateNextChar, 50);

    return () => clearTimeout(timeout);
  }, [text, onComplete, isStarted]);

  // Create array of characters with animated wrappers
  const animatedChars = text.split('').map((char, index) => {
    const isVisible = index < visibleChars;

    return (
      <AnimatePresence key={index} mode="wait">
        {isVisible && (
          <motion.span
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.1 }}
            style={{ 
              display: 'inline-block',
              whiteSpace: preserveWhitespace ? 'pre' : 'normal'
            }}
          >
            {char}
          </motion.span>
        )}
      </AnimatePresence>
    );
  });

  // Component-specific styles
  const componentStyle = {
    display: 'block',
    width: '100%',
    whiteSpace: preserveWhitespace ? 'pre-wrap' as const : 'normal' as const,
    wordBreak: 'break-word' as const
  };

  // Render with specified element type
  const Component = element as any;

  return (
    <Component 
      className={`animated-text ${className} ${isComplete ? 'complete' : ''}`}
      style={componentStyle}
    >
      {animatedChars}
    </Component>
  );
};

export default AnimatedText;
